inline std::optional<study_kick_search::Policy> policy(study_catalog::Kind kind,
                                                      int quarter) noexcept {
    if (!study_catalog::find(kind) || quarter < 0 || quarter > 3) return std::nullopt;
    study_kick_search::Policy list;
    list.count = kind == study_catalog::Kind::O ? 1 : 7;
    const int side = (quarter == 0 || quarter == 3) ? -1 : 1;
    list.offsets = {{{0,0},{0,side},{0,-side},{0,2*side},{0,-2*side},{-1,0},{-2,0}}};
    return list;
}

for (std::size_t index = 0; index < policy.count; ++index) {
    const Offset& offset = policy.offsets[index];

    // Start from a fresh copy every iteration; offsets do not accumulate.
    study_piece::Piece candidate = rotated;

    // Widen the origin before adding so the addition cannot overflow.
    const std::int64_t row =
        static_cast<std::int64_t>(rotated.origin.row) +
        static_cast<std::int64_t>(offset.row);
    const std::int64_t column =
        static_cast<std::int64_t>(rotated.origin.column) +
        static_cast<std::int64_t>(offset.column);

    // Skip offsets whose result does not fit in int.
    if (row < std::numeric_limits<int>::min() ||
        row > std::numeric_limits<int>::max() ||
        column < std::numeric_limits<int>::min() ||
        column > std::numeric_limits<int>::max()) {
        continue;
    }

    candidate.origin.row = static_cast<int>(row);
    candidate.origin.column = static_cast<int>(column);

    // Accept only a fully clear placement; reject outside, occupied and
    // unrepresentable alike.
    if (study_collision::classify(board, candidate) ==
        study_collision::Placement::clear) {
        return Candidate{candidate, index};
    }
}

inline Outcome try_clockwise(const study_grid::Grid& board, study_piece::Piece& piece,
                              study_catalog::Kind kind, int& quarter) noexcept {
    const auto expected = study_rotation::shape_at(kind,quarter);
    const auto list = policy(kind,quarter);
    if (!expected || !list || !study_rotation::same_cells(piece.local,*expected) ||
        study_collision::classify(board,piece)!=study_collision::Placement::clear)
        return {};
    const int next_quarter = (quarter+1)%4;
    const auto shape = study_rotation::shape_at(kind,next_quarter);
    if (!shape) return {};
    auto rotated = piece;
    rotated.local = *shape;
    const auto choice = study_kick_search::first_clear(board,rotated,*list);
    if (!choice) return {study_rotation::Result::blocked,-1};
    piece = choice->piece;
    quarter = next_quarter;
    return {study_rotation::Result::rotated,static_cast<int>(choice->index)};
}

auto turn = study_rotation::Result::blocked; // No requested shape change.
if (clockwise) {
    const auto rotation = study_kicks::try_clockwise(candidate.board_,*candidate.active_,
                                                     candidate.kind_,candidate.quarter_);
    turn = rotation.result;
    candidate.last_rotation_candidate_ = rotation.candidate_index;
    if (turn == study_rotation::Result::invalid) return Step::invalid;
}

if (result != study_round::Step::invalid && result != study_round::Step::stopped &&
    round.last_rotation_candidate() > 0)
    std::printf("rotation accepted: kick candidate=%d\n",round.last_rotation_candidate());
